using System;
using System.Linq;
using System.Windows;
using System.Windows.Automation;
using System.Windows.Controls;
using System.Windows.Markup;
using System.Windows.Media;
namespace Postbox {
    public static class UiPolish {
        public static ContextMenu TrayMenu() {
            var menu = (ContextMenu)XamlReader.Parse("<ContextMenu xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' HasDropShadow='False' MinWidth='208'><ContextMenu.Template><ControlTemplate TargetType='ContextMenu'><Border Background='#0D2419' BorderBrush='#3A8C5E' BorderThickness='1' CornerRadius='14' Padding='8'><ItemsPresenter KeyboardNavigation.DirectionalNavigation='Cycle'/></Border></ControlTemplate></ContextMenu.Template><ContextMenu.Resources><Style TargetType='MenuItem'><Setter Property='Background' Value='#3A8C5E'/><Setter Property='Foreground' Value='White'/><Setter Property='FontSize' Value='12'/><Setter Property='Height' Value='38'/><Setter Property='Margin' Value='0,4'/><Setter Property='Cursor' Value='Hand'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='MenuItem'><Border x:Name='bubble' CornerRadius='19' Background='{TemplateBinding Background}' Padding='16,8'><ContentPresenter ContentSource='Header' VerticalAlignment='Center' RecognizesAccessKey='True'/></Border><ControlTemplate.Triggers><Trigger Property='IsHighlighted' Value='True'><Setter TargetName='bubble' Property='Background' Value='#28503A'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter TargetName='bubble' Property='Opacity' Value='0.4'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style></ContextMenu.Resources></ContextMenu>");
            return menu;
        }
        public static ListBox CalendarChoices() {
            return (ListBox)XamlReader.Parse(@"<ListBox xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' SelectionMode='Multiple' Background='#0D2419' Foreground='White' BorderBrush='#3A8C5E' BorderThickness='1' Padding='6' MinHeight='100' MaxHeight='240' ScrollViewer.HorizontalScrollBarVisibility='Disabled' ScrollViewer.VerticalScrollBarVisibility='Auto' HorizontalContentAlignment='Stretch'>
<ListBox.Template><ControlTemplate TargetType='ListBox'><Border Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='{TemplateBinding BorderThickness}' CornerRadius='12' Padding='{TemplateBinding Padding}'><ScrollViewer Focusable='False' CanContentScroll='True'><ItemsPresenter/></ScrollViewer></Border></ControlTemplate></ListBox.Template>
<ListBox.ItemContainerStyle><Style TargetType='ListBoxItem'><Setter Property='Margin' Value='0,3'/><Setter Property='Padding' Value='12,10'/><Setter Property='HorizontalContentAlignment' Value='Stretch'/><Setter Property='Background' Value='#28503A'/><Setter Property='Foreground' Value='White'/><Setter Property='Template'><Setter.Value><ControlTemplate TargetType='ListBoxItem'><Border x:Name='row' Background='{TemplateBinding Background}' CornerRadius='10' Padding='{TemplateBinding Padding}' BorderThickness='1' BorderBrush='Transparent'><ContentPresenter/></Border><ControlTemplate.Triggers><Trigger Property='IsSelected' Value='True'><Setter TargetName='row' Property='Background' Value='#3A8C5E'/></Trigger><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='row' Property='BorderBrush' Value='#75D49B'/></Trigger><Trigger Property='IsKeyboardFocusWithin' Value='True'><Setter TargetName='row' Property='BorderBrush' Value='White'/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style></ListBox.ItemContainerStyle>
<ListBox.ItemTemplate><DataTemplate><CheckBox Focusable='False' Foreground='White' VerticalContentAlignment='Center' IsChecked='{Binding IsSelected, RelativeSource={RelativeSource AncestorType=ListBoxItem}, Mode=TwoWay}' ToolTip='{Binding Email}'><StackPanel><TextBlock Text='{Binding Name}' FontSize='14' FontWeight='SemiBold' Foreground='White' TextWrapping='Wrap'/><TextBlock x:Name='access' Text='Can receive new events' FontSize='11' Foreground='White' Margin='0,3,0,0'/></StackPanel></CheckBox><DataTemplate.Triggers><DataTrigger Binding='{Binding Writable}' Value='False'><Setter TargetName='access' Property='Text' Value='Read-only calendar'/></DataTrigger></DataTemplate.Triggers></DataTemplate></ListBox.ItemTemplate></ListBox>");
        }
        public static ListBox ReminderList() {
            var list = CalendarChoices(); list.SelectionMode = SelectionMode.Single; list.MaxHeight = Double.PositiveInfinity; list.Margin = new Thickness(0, 12, 0, 12);
            list.ItemTemplate = (DataTemplate)XamlReader.Parse(@"<DataTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'><StackPanel ToolTip='{Binding Email}'><TextBlock Text='{Binding Title}' FontSize='14' FontWeight='SemiBold' Foreground='White' TextWrapping='Wrap'/><TextBlock Text='{Binding Start, StringFormat={}{0:ddd\, d MMM yyyy HH:mm}}' FontSize='12' Foreground='White' Margin='0,4,0,0'/><TextBlock Text='{Binding Location}' FontSize='12' Foreground='White' TextWrapping='Wrap' Margin='0,3,0,0'/></StackPanel></DataTemplate>");
            return list;
        }
        private static ControlTemplate pill;
        private static void Pill(Button button) {
            if (pill == null) pill = (ControlTemplate)XamlReader.Parse("<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' TargetType='Button'><Border x:Name='pill' Background='{TemplateBinding Background}' CornerRadius='18' Padding='{TemplateBinding Padding}' BorderThickness='{TemplateBinding BorderThickness}' BorderBrush='{TemplateBinding BorderBrush}'><ContentPresenter HorizontalAlignment='{TemplateBinding HorizontalContentAlignment}' VerticalAlignment='Center'/></Border><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='pill' Property='Opacity' Value='0.82'/></Trigger><Trigger Property='IsPressed' Value='True'><Setter TargetName='pill' Property='Opacity' Value='0.65'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter TargetName='pill' Property='Opacity' Value='0.4'/></Trigger><Trigger Property='IsKeyboardFocused' Value='True'><Setter TargetName='pill' Property='BorderThickness' Value='1'/><Setter TargetName='pill' Property='BorderBrush' Value='White'/></Trigger></ControlTemplate.Triggers></ControlTemplate>");
            button.Template = pill;
        }
        private sealed class Caption : StackPanel { public string Text; public override string ToString() { return Text; } }
        public static void Navigation(Button button, string caption, string kind, bool iconOnly) {
            string path = kind == "wrench" ? "M14.7 6.3 A1 1 0 0 0 14.7 7.7 L16.3 9.3 A1 1 0 0 0 17.7 9.3 L21 6 A6 6 0 0 1 13.06 13.94 L5.5 21.5 A2.12 2.12 0 0 1 2.5 18.5 L10.06 10.94 A6 6 0 0 1 18 3 Z" : kind == "calendar" ? "M3 5 L21 5 L21 21 L3 21 Z M3 10 L21 10 M7 2 L7 7 M17 2 L17 7 M7 14 L10 14 M14 14 L17 14 M7 18 L10 18" : "M2 6 L18 6 L18 20 L2 20 Z M2 6 L10 13 L18 6 M20 1 L20 7 M17 4 L23 4";
            var drawing = new GeometryDrawing(null, new Pen(Brushes.White, 1.7) { StartLineCap = PenLineCap.Round, EndLineCap = PenLineCap.Round, LineJoin = PenLineJoin.Round }, Geometry.Parse(path)); drawing.Freeze(); var source = new DrawingImage(drawing); source.Freeze();
            var panel = new Caption { Text = caption, Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center, HorizontalAlignment = HorizontalAlignment.Center, UseLayoutRounding = true };
            panel.Children.Add(new Image { Source = source, Width = 20, Height = 20, Stretch = Stretch.Uniform, SnapsToDevicePixels = true, Margin = new Thickness(0, 0, iconOnly ? 0 : 9, 0) }); if (!iconOnly) panel.Children.Add(new TextBlock { Text = caption, FontSize = 12, FontWeight = FontWeights.SemiBold, Foreground = Brushes.White, VerticalAlignment = VerticalAlignment.Center });
            button.Content = panel; Pill(button); AutomationProperties.SetName(button, caption);
        }
        public static void MailAction(Button button) { Pill(button); button.Height = 32; button.MinHeight = 32; button.Padding = new Thickness(12, 6, 12, 6); button.Margin = new Thickness(0, 4, 8, 4); button.FontSize = 12; button.FontWeight = FontWeights.Normal; button.Background = Theme.B("SidebarAccent"); button.Foreground = Brushes.White; button.VerticalAlignment = VerticalAlignment.Top; button.HorizontalAlignment = HorizontalAlignment.Left; }
        private static readonly DependencyProperty SettingsPrimary = DependencyProperty.RegisterAttached("SettingsPrimary", typeof(bool?), typeof(UiPolish), new PropertyMetadata(null));
        private static DataTemplate settingsCaption;
        public static void SettingsButton(Button button) { Pill(button);
            var primary = (bool?)button.GetValue(SettingsPrimary); if (!primary.HasValue) { var color = button.Background as SolidColorBrush; primary = color != null && (color.Color == ((SolidColorBrush)Theme.B("Accent")).Color || color.Color == ((SolidColorBrush)Theme.B("SidebarAccent")).Color); button.SetValue(SettingsPrimary, primary); }
            button.Background = Theme.B(primary.Value ? "SidebarAccent" : "SidebarSelected"); button.Foreground = Brushes.White; button.MinHeight = 36; button.Padding = new Thickness(14, 8, 14, 8); button.HorizontalAlignment = HorizontalAlignment.Left; button.VerticalAlignment = VerticalAlignment.Center;
            button.Margin = new Thickness(button.Margin.Left, Math.Max(4, button.Margin.Top), Math.Max(10, button.Margin.Right), Math.Max(10, button.Margin.Bottom));
            if (button.Content is string) { if (settingsCaption == null) settingsCaption = (DataTemplate)XamlReader.Parse("<DataTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation'><TextBlock Text='{Binding}' TextWrapping='Wrap' TextAlignment='Center'/></DataTemplate>"); button.ContentTemplate = settingsCaption; }
        }
        public static void SettingsTree(DependencyObject root) { var button = root as Button; if (button != null) SettingsButton(button); foreach (var child in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>().ToList()) SettingsTree(child); }
    }
